-- Original Zanrizon Traders schema (before DeepQr), copied from the live project catalog.
create table public.activity_log (id uuid not null default gen_random_uuid(), business_id uuid not null, type text, description text, by_name text, created_at timestamp with time zone default now());
create table public.adjustments (id uuid not null default gen_random_uuid(), business_id uuid not null, shop_id uuid, product_id uuid, old_qty numeric, new_qty numeric, reason text, date date default CURRENT_DATE, by_name text, created_at timestamp with time zone default now());
create table public.businesses (id uuid not null default gen_random_uuid(), name text not null, short text default 'BIZ'::text, currency text default 'USD'::text, tax numeric default 0, low_stock integer default 10, receipt_footer text default 'Thank you for your business'::text, phone text default ''::text, email text default ''::text, address text default ''::text, owner_auth_id uuid, created_at timestamp with time zone default now());
create table public.categories (id uuid not null default gen_random_uuid(), business_id uuid not null, name text not null);
create table public.expenses (id uuid not null default gen_random_uuid(), business_id uuid not null, shop_id uuid, category text default 'Other'::text, amount numeric not null default 0, description text default ''::text, date date default CURRENT_DATE, by_name text, created_at timestamp with time zone default now());
create table public.members (id uuid not null default gen_random_uuid(), business_id uuid not null, auth_user_id uuid, name text not null, username text, role text not null, shop_id uuid, theme text default 'light'::text, created_at timestamp with time zone default now(), avatar text);
create table public.order_items (id uuid not null default gen_random_uuid(), order_id uuid not null, business_id uuid not null, product_id uuid, shop_id uuid, qty_ordered numeric not null, qty_received numeric not null default 0, status text not null default 'pending'::text, received_by text, received_at timestamp with time zone);
create table public.orders (id uuid not null default gen_random_uuid(), business_id uuid not null, shop_id uuid, ref text default ''::text, note text default ''::text, status text not null default 'pending'::text, created_by text, created_at timestamp with time zone default now());
create table public.products (id uuid not null default gen_random_uuid(), business_id uuid not null, code text not null, name text not null, category text default 'General'::text, unit text default 'unit'::text, cost numeric default 0, price numeric default 0, tax numeric default 0, barcode text not null, active boolean default true, created_at timestamp with time zone default now(), low_stock integer);
create table public.purchases (id uuid not null default gen_random_uuid(), business_id uuid not null, shop_id uuid, product_id uuid, qty numeric not null, cost numeric not null default 0, supplier text default ''::text, ref text default ''::text, date date default CURRENT_DATE, by_name text, created_at timestamp with time zone default now());
create table public.sale_lines (id uuid not null default gen_random_uuid(), sale_id uuid not null, business_id uuid not null, product_id uuid, name text, code text, qty numeric not null, price numeric not null, tax numeric default 0);
create table public.sales (id uuid not null default gen_random_uuid(), business_id uuid not null, shop_id uuid, receipt text not null, date date default CURRENT_DATE, time text, subtotal numeric default 0, tax numeric default 0, total numeric default 0, payment text default 'Cash'::text, customer text default 'Walk-in'::text, cashier_name text, created_at timestamp with time zone default now());
create table public.shops (id uuid not null default gen_random_uuid(), business_id uuid not null, name text not null, type text default 'shop'::text, created_at timestamp with time zone default now());
create table public.stock_levels (business_id uuid not null, shop_id uuid not null, product_id uuid not null, qty numeric not null default 0);
create table public.transfers (id uuid not null default gen_random_uuid(), business_id uuid not null, from_shop uuid, to_shop uuid, product_id uuid, qty numeric not null, note text default ''::text, date date default CURRENT_DATE, by_name text, created_at timestamp with time zone default now(), status text not null default 'completed'::text, received_by text, received_at timestamp with time zone);
create table public.username_directory (username text not null, email text not null, business_id uuid not null, created_at timestamp with time zone default now());
alter table expenses add constraint expenses_pkey PRIMARY KEY (id);
alter table businesses add constraint businesses_pkey PRIMARY KEY (id);
alter table sales add constraint sales_pkey PRIMARY KEY (id);
alter table members add constraint members_pkey PRIMARY KEY (id);
alter table members add constraint members_auth_user_id_key UNIQUE (auth_user_id);
alter table members add constraint members_business_id_username_key UNIQUE (business_id, username);
alter table username_directory add constraint username_directory_pkey PRIMARY KEY (username);
alter table shops add constraint shops_pkey PRIMARY KEY (id);
alter table categories add constraint categories_pkey PRIMARY KEY (id);
alter table categories add constraint categories_business_id_name_key UNIQUE (business_id, name);
alter table products add constraint products_pkey PRIMARY KEY (id);
alter table products add constraint products_business_id_code_key UNIQUE (business_id, code);
alter table products add constraint products_business_id_barcode_key UNIQUE (business_id, barcode);
alter table stock_levels add constraint stock_levels_pkey PRIMARY KEY (shop_id, product_id);
alter table purchases add constraint purchases_pkey PRIMARY KEY (id);
alter table transfers add constraint transfers_pkey PRIMARY KEY (id);
alter table adjustments add constraint adjustments_pkey PRIMARY KEY (id);
alter table sale_lines add constraint sale_lines_pkey PRIMARY KEY (id);
alter table activity_log add constraint activity_log_pkey PRIMARY KEY (id);
alter table orders add constraint orders_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text])));
alter table orders add constraint orders_pkey PRIMARY KEY (id);
alter table order_items add constraint order_items_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'received'::text])));
alter table order_items add constraint order_items_pkey PRIMARY KEY (id);
alter table transfers add constraint transfers_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text])));
alter table members add constraint members_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'manager'::text, 'main_operator'::text, 'cashier'::text])));
alter table adjustments add constraint adjustments_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;
alter table adjustments add constraint adjustments_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL;
alter table businesses add constraint businesses_owner_auth_id_fkey FOREIGN KEY (owner_auth_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table expenses add constraint expenses_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table expenses add constraint expenses_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;
alter table sales add constraint sales_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table members add constraint members_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table members add constraint members_auth_user_id_fkey FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table username_directory add constraint username_directory_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table shops add constraint shops_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table categories add constraint categories_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table products add constraint products_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table stock_levels add constraint stock_levels_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table stock_levels add constraint stock_levels_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE CASCADE;
alter table stock_levels add constraint stock_levels_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE;
alter table purchases add constraint purchases_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table purchases add constraint purchases_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;
alter table purchases add constraint purchases_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL;
alter table transfers add constraint transfers_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table transfers add constraint transfers_from_shop_fkey FOREIGN KEY (from_shop) REFERENCES shops(id) ON DELETE SET NULL;
alter table transfers add constraint transfers_to_shop_fkey FOREIGN KEY (to_shop) REFERENCES shops(id) ON DELETE SET NULL;
alter table transfers add constraint transfers_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL;
alter table adjustments add constraint adjustments_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table sales add constraint sales_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;
alter table sale_lines add constraint sale_lines_sale_id_fkey FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE;
alter table sale_lines add constraint sale_lines_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table sale_lines add constraint sale_lines_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL;
alter table activity_log add constraint activity_log_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table orders add constraint orders_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table orders add constraint orders_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;
alter table order_items add constraint order_items_order_id_fkey FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE;
alter table order_items add constraint order_items_business_id_fkey FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE;
alter table order_items add constraint order_items_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL;
alter table order_items add constraint order_items_shop_id_fkey FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION public.my_business_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ select business_id from members where auth_user_id = auth.uid() limit 1 $function$;
CREATE OR REPLACE FUNCTION public.my_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ select role from members where auth_user_id = auth.uid() limit 1 $function$;

alter table public.products enable row level security;
alter table public.purchases enable row level security;
alter table public.sales enable row level security;
alter table public.sale_lines enable row level security;
alter table public.members enable row level security;
alter table public.businesses enable row level security;
