create policy products_all on public.products for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy purchases_all on public.purchases for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy sales_all on public.sales for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy sale_lines_all on public.sale_lines for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy members_delete on public.members for DELETE to public using (((business_id = my_business_id()) AND (my_role() = ANY (ARRAY['owner'::text, 'manager'::text])) AND (auth_user_id <> auth.uid())));
create policy members_insert on public.members for INSERT to public with check (((auth.uid() IS NOT NULL) AND ((auth_user_id = auth.uid()) OR (my_role() = ANY (ARRAY['owner'::text, 'manager'::text])))));
create policy members_select on public.members for SELECT to public using ((business_id = my_business_id()));
create policy members_update on public.members for UPDATE to public using (((business_id = my_business_id()) AND ((auth_user_id = auth.uid()) OR (my_role() = ANY (ARRAY['owner'::text, 'manager'::text])))));
create policy biz_insert on public.businesses for INSERT to public with check ((auth.uid() IS NOT NULL));
create policy biz_select on public.businesses for SELECT to public using (((id = my_business_id()) OR (owner_auth_id = auth.uid())));
create policy biz_update on public.businesses for UPDATE to public using (((id = my_business_id()) AND (my_role() = ANY (ARRAY['owner'::text, 'manager'::text]))));
create policy dir_delete on public.username_directory for DELETE to public using (((business_id = my_business_id()) AND (my_role() = ANY (ARRAY['owner'::text, 'manager'::text]))));
create policy dir_insert on public.username_directory for INSERT to public with check (((business_id = my_business_id()) AND (my_role() = ANY (ARRAY['owner'::text, 'manager'::text]))));
create policy dir_select on public.username_directory for SELECT to public using (true);
create policy categories_all on public.categories for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy stock_all on public.stock_levels for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy adjustments_all on public.adjustments for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy expenses_all on public.expenses for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy activity_all on public.activity_log for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy shops_all on public.shops for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy orders_all on public.orders for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy order_items_all on public.order_items for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
create policy transfers_all on public.transfers for ALL to public using ((business_id = my_business_id())) with check ((business_id = my_business_id()));
